; sfx.asm - generated by WebSidTracker. Edit the sound effects in the tracker, not here.
; websidtracker format 2, release 0.2.6
; Play one with:  lda #SFX_NAME : ldx #voice : jsr sfx_play       (voice 0, 1 or 2; see docs/player.md)
; sfx_voice holds the voice each effect was made for in the tracker; the game may use another one.

SFX_DODGE               = 0    ; Dodge
SFX_CHAPTER             = 1    ; Chapter
SFX_HIT                 = 2    ; Hit
SFX_HIT_BODY            = 3    ; Hit body

sfx_lo
        !byte <sfx_0, <sfx_1, <sfx_2, <sfx_3

sfx_hi
        !byte >sfx_0, >sfx_1, >sfx_2, >sfx_3

sfx_voice
        !byte 2, 2, 2, 0

sfx_count
        !byte 4

sfx_0    ; Dodge
        !byte 1                         ; speed: frames per tick
        !byte $61, 4                    ; instrument 4
        !byte $48, 6                    ; C-6, 6 ticks
        !byte $FF                       ; end of the effect

sfx_1    ; Chapter
        !byte 1                         ; speed: frames per tick
        !byte $61, 5                    ; instrument 5
        !byte $39, 24                    ; A-4, 24 ticks
        !byte $33, 36                    ; D#4, 36 ticks
        !byte $FF                       ; end of the effect

sfx_2    ; Hit
        !byte 1                         ; speed: frames per tick
        !byte $61, 6                    ; instrument 6
        !byte $3C, 50                    ; C-5, 50 ticks
        !byte $FF                       ; end of the effect

sfx_3    ; Hit body
        !byte 1                         ; speed: frames per tick
        !byte $61, 7                    ; instrument 7
        !byte $21, 30                    ; A-2, 30 ticks
        !byte $FF                       ; end of the effect
